"use client";import{useEffect,useState}from"react";import type{GalleryItem}from"../../lib/gallery";export default function Gallery(){const[items,setItems]=useState<GalleryItem[]>([]);useEffect(()=>{fetch("/api/gallery").then(r=>r.json()).then(setItems)},[]);return <main className="orderPage" dir="rtl"><a className="back" href="/">← بازگشت به صفحه اصلی</a><section className="galleryPage"><small>رایامهر</small><h1>گالری تصاویر</h1><p>گوشه‌ای از پکیج‌ها و مسیر شیرین یادگیری کودکان.</p><div>{items.map(x=><figure key={x.id}><img src={x.src} alt={x.title}/><figcaption>{x.title}</figcaption></figure>)}</div></section></main>}
